output_text:
[
  {
    "id": "must_take_entry_cart",
    "text": "A shopper is obliged to take the entry cart at the cart station before continuing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "at_entry_cart_station": "at(1,5)",
        "entry_cart_available": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "take_entry_cart": {
          "pre": {
            "and": [
              "entry_cart_available",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entry_cart"
    }
  },
  {
    "id": "no_passing_cart_station",
    "text": "A shopper may not move away from the entry cart station while the assigned cart is still parked there.",
    "abstraction": {
      "state_properties": {
        "entry_cart_available": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "leave_entry_cart_behind": {
          "pre": {
            "and": [
              "entry_cart_available",
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_entry_cart_behind"
    }
  },
  {
    "id": "items_only_with_cart",
    "text": "Merchandise may only be picked up while the shopper has the cart.",
    "abstraction": {
      "state_properties": {
        "shopping_with_cart": "hasCart",
        "shopping_without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "pickup_item_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "shopping_without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pickup_item_without_cart"
    }
  },
  {
    "id": "hands_must_stay_free",
    "text": "A shopper is prohibited from carrying groceries by hand rather than keeping them in the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull",
        "hands_free": {
          "not": "handFull"
        }
      },
      "events": {
        "becomes_hand_carrying": {
          "pre": {
            "not": "handFull"
          },
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_by_hand"
    }
  },
  {
    "id": "return_cart_to_bay",
    "text": "After taking a cart, the shopper is obliged to return it to the cart-return bay at cell (0,1) before leaving.",
    "abstraction": {
      "state_properties": {
        "at_return_bay": "at(0,1)",
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "take_cart": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "at_return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "no_abandon_cart_elsewhere",
    "text": "A shopper is forbidden to leave the cart anywhere other than the designated return bay at (0,1).",
    "abstraction": {
      "state_properties": {
        "at_return_bay": "at(0,1)",
        "outside_return_bay": {
          "not": "at(0,1)"
        }
      },
      "events": {
        "abandon_cart_outside_bay": {
          "pre": {
            "and": [
              "hasCart",
              "LEAVE_CART",
              "outside_return_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "abandon_cart_outside_bay"
    }
  },
  {
    "id": "exit_only_after_cart_return",
    "text": "The shopper may exit only after the cart has been parked in the return bay and is no longer being held.",
    "abstraction": {
      "state_properties": {
        "cart_returned": "cartAt(0,1)",
        "not_holding_cart": {
          "not": "hasCart"
        },
        "ready_to_exit": {
          "and": [
            "cart_returned",
            "not_holding_cart"
          ]
        }
      },
      "events": {
        "unready_exit": {
          "pre": {
            "and": [
              "EXIT",
              {
                "not": "ready_to_exit"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "unready_exit"
    }
  },
  {
    "id": "cart_not_in_narrow_right_aisle",
    "text": "Carts are not allowed in the narrow right-hand aisle beyond the egg shelf, so a shopper with a cart must not enter cells (7,4) or (8,4) or continue east or south from (6,4).",
    "abstraction": {
      "state_properties": {
        "right_hand_narrow_aisle": {
          "or": [
            "at(7,4)",
            "at(8,4)"
          ]
        },
        "at_egg_shelf_with_cart": {
          "and": [
            "at(6,4)",
            "hasCart"
          ]
        }
      },
      "events": {
        "push_cart_into_narrow_aisle": {
          "pre": {
            "and": [
              "hasCart",
              {
                "or": [
                  "at(7,4)",
                  "at(8,4)"
                ]
              }
            ]
          },
          "post": null
        },
        "continue_from_egg_shelf_with_cart": {
          "pre": {
            "and": [
              "at_egg_shelf_with_cart",
              {
                "or": [
                  "E",
                  "S"
                ]
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "push_cart_into_narrow_aisle",
          "continue_from_egg_shelf_with_cart"
        ]
      }
    }
  }
]
